import sys, requests, time
sys.path.insert(0, '/claude_home')
from bioblend.galaxy import GalaxyInstance

api_key = '[REDACTED_GALAXY_API_KEY]'
gi = GalaxyInstance('https://usegalaxy.org', key=api_key)
hist_id = 'bbd44e69cb8906b56318fe8182c6cb16'
headers = {'x-api-key': api_key}

contents = gi.histories.show_history(hist_id, contents=True)

# Get HDA IDs for the 4 missing HIDs: 136, 137, 138, 142
missing_hids = [136, 137, 138, 142]
hda_map = {}
for item in contents:
    hid = item.get('hid')
    if hid in missing_hids:
        coll_id = item['id']
        try:
            coll = gi.histories.show_dataset_collection(hist_id, coll_id)
            elements = coll.get('elements', [])
            for el in elements:
                el_obj = el.get('element_object', el.get('object', {}))
                hda_map[hid] = el_obj.get('id')
        except Exception as e:
            print(f'Error for HID {hid}: {e}')

CODING_SO = {
    'synonymous_variant', 'missense_variant', 'frameshift_variant',
    'inframe_insertion', 'inframe_deletion', 'stop_gained', 'stop_lost',
    'start_lost', 'coding_sequence_variant', 'protein_altering_variant',
}

for hid in missing_hids:
    hda_id = hda_map.get(hid)
    if not hda_id:
        print(f'HID {hid}: no HDA found')
        continue

    time.sleep(2)  # Small delay between requests
    url = f'https://usegalaxy.org/api/histories/{hist_id}/contents/{hda_id}/display'
    r = requests.get(url, headers=headers)

    if r.status_code == 429:
        print(f'HID {hid}: rate limited again, sleeping...')
        time.sleep(10)
        r = requests.get(url, headers=headers)

    if r.status_code != 200:
        print(f'HID {hid}: status {r.status_code}')
        continue

    content = r.content.decode('utf-8', errors='replace')
    lines = content.split('\n')

    local_total = 0
    local_syn = 0

    for i, line in enumerate(lines):
        if i < 2:
            continue
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) < 14:
            continue
        so = fields[13].strip()
        vaf_str = fields[9].strip()
        if so not in CODING_SO:
            continue
        if not vaf_str:
            continue
        try:
            vaf = float(vaf_str)
        except ValueError:
            continue
        if vaf >= 0.3:
            continue
        local_total += 1
        if so == 'synonymous_variant':
            local_syn += 1

    print(f'HID {hid}: total={local_total}, syn={local_syn}')
PYEOF

